"""Генератор catastrophes.json, bunker.json и help.json для «Бункер Live»."""
import json, os

OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'server', 'game', 'data')

def card(cid, title, text, tags, tip, *rest, **extra):
    d = {"id": cid, "title": title, "text": text, "tags": tags, "tip": tip}
    if len(rest) == 3:  # duration, severity, threats
        d["duration"], d["severity"], d["threats"] = rest
    elif len(rest) == 5:  # kind, area_sqm, food_units, sleeping_rooms, items
        d["kind"], d["area_sqm"], d["food_units"], d["sleeping_rooms"], d["items"] = rest
    d.update(extra)
    return d

