def build(meta, rows):
    return {"category": meta[0], "label": meta[1], "icon": meta[2],
            "cards": [card(*r) for r in rows]}

def check_deck(name, deck):
    bad = []
    seen = set()
    for c in deck["cards"]:
        if c["id"] in seen:
            bad.append("dup id " + c["id"])
        seen.add(c["id"])
        if not (80 <= len(c["text"]) <= 200):
            bad.append("text %d %s %s" % (len(c["text"]), c["id"], c["title"]))
        if not (60 <= len(c["tip"]) <= 160):
            bad.append("tip %d %s %s" % (len(c["tip"]), c["id"], c["title"]))
        if not (2 <= len(c["tags"]) <= 4):
            bad.append("tags %s" % c["id"])
    print(name, "cards:", len(deck["cards"]), "problems:", len(bad))
    for b in bad:
        print("   !", b)
    return bad

def check_help(h):
    bad = []
    ids = sorted(p["id"] for p in h["phases"])
    if ids != ["defense", "discussion", "finale", "lobby", "reveal", "voting"]:
        bad.append("phase ids: %s" % ids)
    for p in h["phases"]:
        if not p["title"] or not p["short"] or not p["text"]:
            bad.append("phase empty " + p["id"])
        if not (2 <= len(p["tips"]) <= 4):
            bad.append("phase tips %s %d" % (p["id"], len(p["tips"])))
    if len(h["faq"]) < 10:
        bad.append("faq %d" % len(h["faq"]))
    if len(h["glossary"]) < 8:
        bad.append("glossary %d" % len(h["glossary"]))
    print("help: phases %d, faq %d, glossary %d, problems %d" % (len(h["phases"]), len(h["faq"]), len(h["glossary"]), len(bad)))
    for b in bad:
        print("   !", b)
    return bad

def main():
    problems = 0
    cat = build(("catastrophe", "Катастрофа", "☢"), CATASTROPHES)
    problems += len(check_deck("catastrophes", cat))
    sev = {}
    for c in cat["cards"]:
        sev[c["severity"]] = sev.get(c["severity"], 0) + 1
        if not (2 <= len(c["threats"]) <= 4):
            print("   ! threats", c["id"], len(c["threats"]))
            problems += 1
    print("severity spread:", json.dumps(sev))
    bunk = build(("bunker", "Бункер", "🚪"), BUNKER)
    problems += len(check_deck("bunker", bunk))
    kinds = {}
    for c in bunk["cards"]:
        kinds[c["kind"]] = kinds.get(c["kind"], 0) + 1
        if not (80 <= c["area_sqm"] <= 900):
            print("   ! area", c["id"]); problems += 1
        if not (0 <= c["food_units"] <= 24):
            print("   ! food", c["id"]); problems += 1
        if not (1 <= c["sleeping_rooms"] <= 12):
            print("   ! rooms", c["id"]); problems += 1
        if not (3 <= len(c["items"]) <= 5):
            print("   ! items", c["id"], len(c["items"])); problems += 1
    print("kinds:", json.dumps(kinds))
    problems += len(check_help(HELP))
    for name, deck in (("catastrophes", cat), ("bunker", bunk), ("help", HELP)):
        path = os.path.join(OUT, name + ".json")
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            json.dump(deck, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print("wrote", path)
    print("TOTAL problems:", problems)

main()
